/*
 * Parity check: replay fixture trajectories (generated by
 * scripts/gen-parity-fixture.py from the real numpy policy) through the
 * browser engine and require identical guesses, marks, counts, and labels.
 *
 *   npm run build && node scripts/parity-check.mjs
 */
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { EngineError, loadEngine } from "../dist/engine.js";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const repo = join(root, "..");
const releaseDir =
  process.env.WORDLE_RELEASE_DIR ??
  join(repo, "artifacts/releases/champion-5022-certified");
const proofPath =
  process.env.WORDLE_PROOF_PATH ??
  join(repo, "artifacts/proof/champion-5022-certified/proof.json");

const toArrayBuffer = (b) =>
  b.buffer.slice(b.byteOffset, b.byteOffset + b.byteLength);
const file = (path) => toArrayBuffer(readFileSync(path));

const engine = await loadEngine({
  weights: file(join(releaseDir, "weights.safetensors")),
  words: file(join(releaseDir, "accepted-guesses.txt")),
  manifest: file(join(releaseDir, "payload-manifest.json")),
});
engine.attachProof(file(proofPath));

const fixture = JSON.parse(
  readFileSync(join(root, "testdata/parity.json"), "utf8"),
);

let failures = 0;
const check = (name, cond, detail) => {
  if (!cond) {
    failures += 1;
    console.error(`FAIL ${name}: ${detail}`);
  }
};
const sameRows = (a, b) =>
  a.length === b.length &&
  a.every((row, i) => row.guess === b[i].guess && row.marks === b[i].marks);
const sameList = (a, b) =>
  a.length === b.length && a.every((v, i) => v === b[i]);

check("proof.status", engine.proof.status === "VERIFIED", engine.proof.status);
check(
  "proof binding",
  engine.proof.release?.weights_sha256 === fixture.weights_sha256 &&
    engine.proof.release?.manifest_sha256 === fixture.manifest_sha256,
  "release digests drifted from fixture",
);

for (const c of fixture.solves) {
  const tag = `solve ${c.mode} ${c.word}`;
  let got;
  try {
    got = engine.solve(c.mode, c.word);
  } catch (error) {
    check(tag, false, `threw ${error.message}`);
    continue;
  }
  check(
    tag,
    sameRows(got.rows, c.rows),
    `rows diverged: ${JSON.stringify(got.rows)} vs ${JSON.stringify(c.rows)}`,
  );
  check(
    `${tag} counts`,
    sameList(got.consistent_counts, c.consistent_counts),
    `${got.consistent_counts} vs ${c.consistent_counts}`,
  );
  check(`${tag} outcome`, got.outcome === c.outcome, got.outcome);
  check(
    `${tag} certification`,
    got.certification === c.certification,
    got.certification,
  );
}

for (const a of [...fixture.assists, ...fixture.scripts]) {
  const tag = `assist ${a.mode} ${a.word ?? a.steps[1]?.marks}`;
  let state;
  try {
    state = engine.createAssist(a.mode);
  } catch (error) {
    check(tag, false, `create threw ${error.message}`);
    continue;
  }
  const first = a.steps[0];
  check(
    `${tag} opener`,
    state.pending_guess === first.pending &&
      state.consistent_count === first.consistent_count,
    `${state.pending_guess}/${state.consistent_count} vs ${first.pending}/${first.consistent_count}`,
  );
  for (let i = 1; i < a.steps.length; i += 1) {
    const step = a.steps[i];
    try {
      state = engine.assistFeedback(state.session_id, {
        expected_turn: i,
        pending_guess: state.pending_guess,
        marks: step.marks,
      });
    } catch (error) {
      check(`${tag} step ${i}`, false, `threw ${error.message}`);
      break;
    }
    check(
      `${tag} step ${i}`,
      state.pending_guess === step.pending &&
        state.consistent_count === step.consistent_count &&
        state.terminal === step.terminal &&
        state.outcome === step.outcome,
      `${state.pending_guess}/${state.consistent_count}/${state.terminal}/${state.outcome} vs ${step.pending}/${step.consistent_count}/${step.terminal}/${step.outcome}`,
    );
  }
  check(
    `${tag} counts`,
    sameList(state.consistent_counts, a.consistent_counts),
    `${state.consistent_counts} vs ${a.consistent_counts}`,
  );
}

const nonce = ["zzzzz", "qqqqq", "xxxxx", "vvvvv"].find(
  (w) => !engine.words.includes(w),
);
try {
  engine.solve("normal", nonce);
  check("unknown-word", false, `${nonce} did not throw`);
} catch (error) {
  check(
    "unknown-word",
    error instanceof EngineError && error.code === "unknown-word",
    String(error),
  );
}

if (failures === 0) {
  console.log(
    `PARITY PASS: ${fixture.solves.length} solves, ` +
      `${fixture.assists.length + fixture.scripts.length} assist traces`,
  );
} else {
  console.error(`PARITY FAIL: ${failures} mismatch(es)`);
  process.exit(1);
}
